            iv = v
        elif isinstance(v, float) and v.is_integer():
            iv = int(v)
        elif isinstance(v, str):
            try:
                fv = float(v)
                if not fv.is_integer():
                    continue
                iv = int(fv)
            except ValueError:
                continue
        else:
            continue
        # Discard negatives.
        if iv < 0:
            continue
        counts[iv] = counts.get(iv, 0) + 1
    # Sort bins numerically by value.
